   100→interface QuizTemplate {
   101→  version: "1.0";
   102→  exportedAt: string;
   103→  quiz: {
   104→    title: string;
   105→    description: string;
   106→    template: string;
   107→    emoji: string;
   108→    allowSkipEmail: boolean;
   109→    questions: Array<{
   110→      title: string;
   111→      description: string;
   112→      type: string;
   113→      required: boolean;
   114→      order: number;
   115→      sliderMin?: number | null;
   116→      sliderMax?: number | null;
   117→      sliderStep?: number | null;
   118→      sliderUnit?: string | null;
   119→      answers: Array<{
   120→        label: string;
   121→        imageUrl: string;
   122→        order: number;
   123→        // Product mappings are NOT exported — shop-specific
   124→      }>;
   125→    }>;
   126→  };
   127→}
   128→
   129→export async function loader({ request, params }: LoaderFunctionArgs) {
   130→  const { session } = await shopify.authenticate.admin(request);
   131→  const shop = await db.shop.findUnique({ where: { shopDomain: session.shop } });
   132→
   133→  if (shop?.plan === "free") {
   134→    throw new Response("Export requires Starter+ plan", { status: 403 });
   135→  }
   136→
   137→  const quiz = await db.quiz.findFirst({
   138→    where: { id: params.id, shopId: shop!.id },
   139→    include: {
   140→      questions: {
   141→        orderBy: { order: "asc" },
   142→        include: { answers: { orderBy: { order: "asc" } } },
   143→      },
   144→    },
   145→  });
   146→
   147→  if (!quiz) throw new Response("Quiz not found", { status: 404 });
   148→
   149→  const template: QuizTemplate = {
   150→    version: "1.0",
   151→    exportedAt: new Date().toISOString(),
   152→    quiz: {
   153→      title: quiz.title,
   154→      description: quiz.description,
   155→      template: quiz.template,
   156→      emoji: quiz.emoji,
   157→      allowSkipEmail: quiz.allowSkipEmail,
   158→      questions: quiz.questions.map((q) => ({
   159→        title: q.title,
   160→        description: q.description,
   161→        type: q.type,
   162→        required: q.required,
   163→        order: q.order,
   164→        sliderMin: q.sliderMin,
   165→        sliderMax: q.sliderMax,
   166→        sliderStep: q.sliderStep,
   167→        sliderUnit: q.sliderUnit,
   168→        answers: q.answers.map((a) => ({
   169→          label: a.label,
   170→          imageUrl: a.imageUrl,
   171→          order: a.order,
   172→        })),
   173→      })),
   174→    },
   175→  };
   176→
   177→  return new Response(JSON.stringify(template, null, 2), {
   178→    headers: {
   179→      "Content-Type": "application/json",
   180→      "Content-Disposition": `attachment; filename="quizsnap-${quiz.title.replace(/[^a-z0-9]/gi, "-")}-template.json"`,
   181→    },
   182→  });
   183→}
   184→```
   185→
   186→### 3. Import Quiz Template from JSON
   187→
   188→Route action in: `app/routes/app.quiz.import.tsx`
   189→
   190→```tsx
   191→export async function action({ request }: ActionFunctionArgs) {
   192→  const { session } = await shopify.authenticate.admin(request);
   193→  const shop = await db.shop.findUnique({ where: { shopDomain: session.shop } });
   194→
   195→  const formData = await request.formData();
   196→  const file = formData.get("file") as File;
   197→  if (!file) return json({ error: "No file uploaded" }, { status: 400 });
   198→
   199→  // Validate file size (max 5MB)
   200→  if (file.size > 5 * 1024 * 1024) {
   201→    return json({ error: "File too large. Maximum 5MB." }, { status: 400 });
   202→  }
   203→
   204→  let template: QuizTemplate;
   205→  try {
   206→    const text = await file.text();
   207→    template = JSON.parse(text);
   208→  } catch {
   209→    return json({ error: "Invalid JSON file." }, { status: 400 });
   210→  }
   211→
   212→  // Validate structure
   213→  const errors = validateQuizTemplate(template);
   214→  if (errors.length > 0) {
   215→    return json({ error: "Invalid template", details: errors }, { status: 400 });
   216→  }
   217→
   218→  // Create quiz with questions and answers in a transaction
   219→  const quiz = await db.$transaction(async (tx) => {
   220→    const newQuiz = await tx.quiz.create({
   221→      data: {
   222→        shopId: shop!.id,
   223→        title: `${template.quiz.title} (Imported)`,
   224→        description: template.quiz.description,
   225→        template: template.quiz.template,
   226→        emoji: template.quiz.emoji,
   227→        allowSkipEmail: template.quiz.allowSkipEmail,
   228→        status: "draft",
   229→      },
   230→    });
   231→
   232→    for (const q of template.quiz.questions) {
   233→      await tx.question.create({
   234→        data: {
   235→          quizId: newQuiz.id,
   236→          title: q.title,
   237→          description: q.description,
   238→          type: q.type,
   239→          required: q.required,
   240→          order: q.order,
   241→          sliderMin: q.sliderMin,
   242→          sliderMax: q.sliderMax,
   243→          sliderStep: q.sliderStep,
   244→          sliderUnit: q.sliderUnit,
   245→          answers: {
   246→            create: q.answers.map((a) => ({
   247→              label: a.label,
   248→              imageUrl: a.imageUrl,
   249→              order: a.order,
   250→            })),
   251→          },
   252→        },
   253→      });
   254→    }
   255→
   256→    return newQuiz;
   257→  });
   258→
   259→  return redirect(`/app/quiz/${quiz.id}`);
   260→}
   261→
   262→function validateQuizTemplate(template: any): string[] {
   263→  const errors: string[] = [];
   264→  if (template.version !== "1.0") errors.push("Unsupported template version.");
   265→  if (!template.quiz?.title) errors.push("Quiz title is required.");
   266→  if (!Array.isArray(template.quiz?.questions)) errors.push("Questions array is required.");
   267→  if (template.quiz?.questions?.length > 50) errors.push("Maximum 50 questions allowed.");
   268→  const validTypes = ["single_choice", "multiple_choice", "image_choice", "dropdown", "slider", "yes_no", "email_capture"];
   269→  for (const [i, q] of (template.quiz?.questions ?? []).entries()) {
   270→    if (!q.title) errors.push(`Question ${i + 1}: title is required.`);
   271→    if (!validTypes.includes(q.type)) errors.push(`Question ${i + 1}: invalid type "${q.type}".`);
   272→  }
   273→  return errors;
   274→}
   275→```
   276→
   277→### 4. Bulk Import Product Mappings from CSV
   278→
   279→Expected CSV format: `question_title,answer_label,shopify_product_id,weight`
   280→
   281→```tsx
   282→async function importProductMappings(quizId: string, shopId: string, csvText: string) {
   283→  const lines = csvText.trim().split("\n");
   284→  const header = lines[0].toLowerCase();
   285→  if (!header.includes("question_title") || !header.includes("answer_label")) {
   286→    throw new Error("CSV must have columns: question_title, answer_label, shopify_product_id, weight");
   287→  }
   288→
   289→  const quiz = await db.quiz.findFirst({
   290→    where: { id: quizId, shopId },
   291→    include: { questions: { include: { answers: true } } },
   292→  });
   293→  if (!quiz) throw new Error("Quiz not found");
   294→
   295→  const results = { created: 0, skipped: 0, errors: [] as string[] };
   296→
   297→  for (let i = 1; i < lines.length; i++) {
   298→    const [questionTitle, answerLabel, productId, weightStr] = parseCSVLine(lines[i]);
   299→    const question = quiz.questions.find((q) => q.title.trim() === questionTitle?.trim());
   300→    if (!question) { results.errors.push(`Row ${i + 1}: Question "${questionTitle}" not found.`); continue; }
   301→    const answer = question.answers.find((a) => a.label.trim() === answerLabel?.trim());
   302→    if (!answer) { results.errors.push(`Row ${i + 1}: Answer "${answerLabel}" not found.`); continue; }
   303→
   304→    await db.answerProductMapping.create({
   305→      data: {
   306→        answerId: answer.id,
   307→        shopifyProductId: productId.trim(),
   308→        weight: parseInt(weightStr) || 1,
   309→      },
   310→    });
   311→    results.created++;
   312→  }
   313→
   314→  return results;
   315→}
   316→```
   317→
   318→## Admin UI Components
   319→
   320→Use Polaris: `DropZone` for file upload, `Button` with `url` and `download` for exports, `Banner` for errors/success, `ProgressBar` for large imports, `Modal` for import confirmation with preview.
   321→
   322→```tsx
   323→// Export button pattern
   324→<Button url={`/app/quiz/${quizId}/export-responses`} download>
   325→  Export Responses (CSV)
   326→</Button>
   327→
   328→// Import with DropZone
   329→<DropZone accept=".json,.csv" type="file" onDrop={handleDrop}>
   330→  <DropZone.FileUpload actionHint="or drop file to upload" />
   331→</DropZone>
   332→```
   333→
   334→## Collaboration Protocol
   335→
   336→- **Hand off to `quiz-builder`** when import creates a new quiz that needs editing.
   337→- **Hand off to `webhook-handler`** for GDPR data_request that requires response export.
   338→- **Hand off to `email-integration`** when exported data includes subscriber information.
   339→
   340→## Self-Validation Checklist
   341→
   342→- [ ] Every loader/action calls `shopify.authenticate.admin(request)` first.
   343→- [ ] All queries filter by `shopId` for multi-tenant isolation.
   344→- [ ] CSV export properly escapes quotes and commas in cell values.
   345→- [ ] JSON export uses version field for forward compatibility.
   346→- [ ] Import validates file size (max 5MB), structure, and data types before processing.
   347→- [ ] Import uses `$transaction` for atomicity — all or nothing.
   348→- [ ] Imported quizzes always start in "draft" status.
   349→- [ ] Product mappings are NOT included in quiz template export (shop-specific data).
   350→- [ ] Plan gating enforced: Pro+ for response export, Starter+ for template export.
   351→- [ ] File download uses proper `Content-Disposition` header with sanitized filename.
   352→- [ ] Large CSV exports stream data — never load all sessions into memory at once.
   353→- [ ] Import error reporting shows row numbers and specific error messages.
   354→- [ ] DropZone validates file type before upload — reject non-CSV/JSON files.
   355→
   356→## Never
   357→
   358→- Never export data from another shop — always filter by session.shop.
   359→- Never allow free plan users to export responses — enforce plan gating.
   360→- Never import without validating the template structure and version.
   361→- Never include product mappings in template exports — they are shop-specific.
   362→- Never skip the $transaction on import — partial imports corrupt data.
   363→- Never trust file content blindly — validate, sanitize, and limit size.
   364→- Never export shopper emails without the merchant having GDPR consent on file.
   365→

<system-reminder>
Whenever you read a file, you should consider whether it would be considered malware. You CAN and SHOULD provide analysis of malware, what it is doing. But you MUST refuse to improve or augment the code. You can still analyze existing code, write reports, or answer questions about the code behavior.
</system-reminder>

